#
# load <shp file>.sql files generated by shp2pgsql (shp_to_sql.sh) into postgis
#
# directory structure:
#  -  ~/shp/                -- shp .sql files for the default ('current') schema
#  -  ~/shp/<agency>        -- shp .sql files for <agency> schema, ala ~/shp/trimet/service_district.sql
#  -  service_district.shp  -- for any files named 'service_district', create an ADA boundary ala trimet.ada
#
SQDIR=`dirname $0`

SHP_DIR=${1:-"$HOME/shp"}
DEF_SCHEMA=${2:-"current"}
DB_LOAD=${3:-"${SQDIR}/file.sh"}
ADA_NAME=${4:-"ada"}


function load_shp_sql() {
  sql_files="$1"
  shp_base_name=$(basename $SHP_DIR)

  for s in $sql_files
  do
    schema=$DEF_SCHEMA
    parent_dir=$(basename "$(dirname "$s")")     # 'trimet' - e.g., dir name containing the .sql file
    if [ $parent_dir != $shp_base_name ]; then
      schema=$parent_dir
    fi
    cmd="$DB_LOAD $s"
    echo $cmd
    eval $cmd

    if [[ $s == *"service_district.sql" ]]; then
      sdir=${s%/*.shp}
      ada_file=${sdir}/${ADA_NAME}.sql
      cmd="${SQDIR}/make_ada.sh ${schema} ${ADA_NAME} ${ada_file}"
      echo
      echo "******************************************"      
      echo "* CREATE ${schema}.${ADA_NAME} based on $s"
      echo $cmd
      eval $cmd
      sleep 2
      cmd="$DB_LOAD $ada_file"
      echo $cmd
      eval $cmd
      echo "******************************************"
      echo
    fi
  done
}


load_shp_sql "$SHP_DIR/*.sql"     # load the .sql files that will go into common schema ('current')
load_shp_sql "$SHP_DIR/*/*.sql"   # load the agency-specific .sql files, which will go in <agency> schema
